 * fiber.js — Predicate fibers over the FARS knowledge graph.
 *
 * Implements the fiber functor from:
 *   "The Adjoint Structure of Predication on Bilattice-Valued Fibers"
 *   Section 3.1 (predicate fibers) and Theorem 2 (fiber functor)
 *
 * For each predicate p in the FARS graph, the fiber of p is:
 *
 *   Fib(p) = { ⟨s, o, v⟩ : ⟨s, p, o⟩ ∈ 𝓢 with value v }
 *
 * where 𝓢 is the system of SPO triples (FARS frontmatter assertions) and
 * v ∈ {⊥, t, f, ⊤} is the bilattice-valued epistemic state of the assertion.
 *
 * FARS assertion → bilattice value convention:
 *   - An explicit frontmatter assertion `p: v` has value t (told true).
 *   - A negated assertion (no native syntax yet in FARS) would be f.
 *   - Absent assertion is ⊥ (no information).
 *   - Multiple sources asserting different objects under same (subject, predicate)
 *     yield a contradiction fiber entry at ⊤ (told both) after merge via ⊙.
 *
 * Pure functions. Zero external deps beyond graph.js for loading.
 */
"use strict";

const { extend, T, BOT, TOP, equals, name } = require("./predication.js");

// ── Fiber construction ──────────────────────────────────────────────

/**
 * Build the fiber of a single predicate from a loaded graph.
 *
 * @param {object} graph — loaded EAVT graph (from graph.js ensureGraph/loadRaw).
 *                        Expected shape: { attrs: {id→name}, eavt: [[eid,aid,val],…] }
 * @param {string} predicate — the predicate/attribute name (e.g. "type", "part-of")
 * @returns {Map<string, Map<string, Array>>} — subject → (object → value-list)
 *
 * Each leaf is an array of bilattice values because a single (subject, object)
 * pair may be asserted by multiple sources; merge is separate (see mergeFiber).
 */
function buildFiber(graph, predicate) {
  const attrNameToId = new Map();
  for (const [idStr, pname] of Object.entries(graph.attrs || {})) {
    attrNameToId.set(pname, Number(idStr));
  }

  const aid = attrNameToId.get(predicate);
  if (aid === undefined) return new Map(); // predicate not in graph

  // Also need file-path attribute to identify subjects by their entity id
  const fiber = new Map(); // subject-id → (object-value → [bilattice values])

  for (const [eid, attrId, obj] of graph.eavt) {
    if (attrId !== aid) continue;
    const subject = String(eid);
    const object = typeof obj === "string" ? obj : JSON.stringify(obj);
    if (!fiber.has(subject)) fiber.set(subject, new Map());
    const inner = fiber.get(subject);
    if (!inner.has(object)) inner.set(object, []);
    inner.get(object).push(T); // explicit assertion = told true
  }

  return fiber;
}

